import Mathlib

/-- Let `Dₙ` be the dihedral group of a regular `n`-gon (`n ≥ 3`).
Let `r` be the rotation by angle `2π/n` and let `h` be the reflection across the horizontal axis.
Representing `r` by the usual `2×2` rotation matrix and `h` by the reflection matrix across the
`x`-axis, the desired dihedral relation is the matrix identity `r ⬝ h ⬝ r = h`.

Here we express this purely as an equality of real `2×2` matrices.
-/
theorem srdoty_alg_symmetry_743 (n : ℕ) (hn : 3 ≤ n) :
    (Matrix.of fun i j : Fin 2 =>
        if i = 0 ∧ j = 0 then Real.cos (2 * Real.pi / (n : ℝ))
        else if i = 0 ∧ j = 1 then -Real.sin (2 * Real.pi / (n : ℝ))
        else if i = 1 ∧ j = 0 then Real.sin (2 * Real.pi / (n : ℝ))
        else if i = 1 ∧ j = 1 then Real.cos (2 * Real.pi / (n : ℝ))
        else 0)
      ⬝ (Matrix.diagonal fun i : Fin 2 => if i = 0 then (1 : ℝ) else (-1 : ℝ))
      ⬝ (Matrix.of fun i j : Fin 2 =>
        if i = 0 ∧ j = 0 then Real.cos (2 * Real.pi / (n : ℝ))
        else if i = 0 ∧ j = 1 then -Real.sin (2 * Real.pi / (n : ℝ))
        else if i = 1 ∧ j = 0 then Real.sin (2 * Real.pi / (n : ℝ))
        else if i = 1 ∧ j = 1 then Real.cos (2 * Real.pi / (n : ℝ))
        else 0)
      = (Matrix.diagonal fun i : Fin 2 => if i = 0 then (1 : ℝ) else (-1 : ℝ)) := by
