import Mathlib

open Real

/-- With `H0 = diag(1, -1)` and the real rotation matrix by angle `2*θ`,
we have `R(2θ) * H0 * R(2θ) = H0` for all real `θ`.

Here
`H0 = [[1, 0], [0, -1]]` and
`R(2θ) = [[cos(2θ), -sin(2θ)], [sin(2θ), cos(2θ)]]`. -/
theorem rotation_conj_H0 (θ : ℝ) :
    let H0 : Matrix (Fin 2) (Fin 2) ℝ :=
      Matrix.of fun i j : Fin 2 =>
        if (i = 0 ∧ j = 0) then (1 : ℝ)
        else if (i = 1 ∧ j = 1) then (-1 : ℝ)
        else 0
    let R : Matrix (Fin 2) (Fin 2) ℝ :=
      Matrix.of fun i j : Fin 2 =>
        if (i = 0 ∧ j = 0) then Real.cos (2 * θ)
        else if (i = 0 ∧ j = 1) then -Real.sin (2 * θ)
        else if (i = 1 ∧ j = 0) then Real.sin (2 * θ)
        else if (i = 1 ∧ j = 1) then Real.cos (2 * θ)
        else 0
    R ⬝ H0 ⬝ R = H0 := by
